USE health_ai_platform;

-- ============================================================
-- Real policy content for the 5 core Call Center knowledge_docs
-- (v1/v2/v3 of each = 15 rows total), replacing the Faker
-- gibberish generated by generate_seed_data.py.
-- ============================================================

-- --- Call Handling Script - Benefits -----------------------------
UPDATE knowledge_docs SET content = 'Benefits calls follow a standard four-step structure after identity verification: (1) acknowledge the specific benefit question and restate it back to confirm understanding, (2) look up the member current plan and benefit accumulator status before answering, never from memory or general plan assumptions, (3) provide the specific answer with the relevant dollar amounts or coverage percentages, and (4) ask if there is a related question before closing, since benefit questions frequently come in pairs (e.g. a deductible question followed by a copay question). Agents should not guess at coverage details when the member plan document is ambiguous; escalate to a benefits specialist per the Coverage Question Escalation Guide rather than provide an uncertain answer.'
WHERE dept_id = 4 AND title = 'Call Handling Script - Benefits';

UPDATE knowledge_docs SET content = 'Revision 2 adds an explicit plan-year clarification step before step 2 in the original script: agents must confirm which plan year the member is asking about, since a benefits question asked in December is often about the following year, not the current one, and answering with the wrong year plan details was identified as a common source of member confusion. This revision also shortens the standard call length target from an unstated expectation to a specific 6-minute average for straightforward benefits questions, to help agents calibrate pacing without rushing member understanding.'
WHERE dept_id = 4 AND title = 'Call Handling Script - Benefits v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds a documentation requirement to the standard script: the specific benefit figures quoted to the member (dollar amounts, percentages, remaining deductible) must be logged in the call notes field, not just that a benefits question was answered, since member disputes about what they were told previously were difficult to resolve without a record of the exact figures given. This revision also formalizes the related-question prompt from revision 2 as a required step, not an optional courtesy, given data showing a meaningful share of members called back within a day with a related question that could have been addressed on the first call.'
WHERE dept_id = 4 AND title = 'Call Handling Script - Benefits v3';

-- --- Escalation to Grievance Unit SOP -----------------------------
UPDATE knowledge_docs SET content = 'A call is escalated to the Member Services grievance unit when the member expresses formal dissatisfaction that goes beyond a simple service issue the agent can resolve directly, particularly complaints involving a provider, a claim denial the member believes was wrong, or any allegation of discrimination or unfair treatment. Before escalating, the agent should attempt to fully understand and document the specific concern, since an incomplete handoff often results in the member having to repeat their story to the grievance team. The agent should tell the member directly that the call is being escalated and set a realistic expectation for follow-up timing rather than leaving them uncertain about next steps.'
WHERE dept_id = 4 AND title = 'Escalation to Grievance Unit SOP';

UPDATE knowledge_docs SET content = 'Revision 2 adds a warm-transfer preference over a cold handoff wherever staffing allows: rather than simply logging the escalation and ending the call, the agent should attempt to connect the member directly with an available grievance unit representative while still on the line, since members reported frustration at having to re-explain a complaint from scratch on a callback. This revision also lowers the threshold for escalation slightly from the original SOP: a member who explicitly uses the word grievance or complaint should be escalated even if the underlying issue seems minor to the agent, since member-perceived severity, not agent judgment, determines whether the formal process applies.'
WHERE dept_id = 4 AND title = 'Escalation to Grievance Unit SOP v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds a same-day escalation requirement for any complaint involving a safety concern, distinct from the standard grievance timeline: a warm transfer is not sufficient if the grievance unit is unavailable, and the call must be escalated to a supervisor directly rather than queued for a standard callback. This revision also formalizes the documentation standard from the general Escalation to Grievance Unit SOP: the specific concern must be recorded in the member own words where possible, not paraphrased by the agent, since the grievance unit found paraphrased summaries sometimes lost important detail from the original complaint.'
WHERE dept_id = 4 AND title = 'Escalation to Grievance Unit SOP v3';

-- --- HIPAA Verbal Verification SOP -----------------------------
UPDATE knowledge_docs SET content = 'Before discussing any member-specific information over the phone, the agent must verify the caller identity using at least two of the following: full name, date of birth, member ID number, or the address on file. A caller who cannot provide sufficient verification information may not receive any member-specific details, including whether a member is enrolled at all, and should be directed to the written verification process instead. Calls from someone other than the member (a spouse, an adult child, a provider office) require the member own prior written authorization on file before any information is shared, verified against the authorization record, not simply taken on the caller word.'
WHERE dept_id = 4 AND title = 'HIPAA Verbal Verification SOP';

UPDATE knowledge_docs SET content = 'Revision 2 adds a specific exception process to the general authorization requirement in revision 1: a legal guardian or a parent calling about a minor dependent may be verified through the guardianship or dependent relationship already on file, without requiring the separate written authorization needed for other third-party callers, since that relationship is itself sufficient authorization under the plan governing documents. This revision also clarifies that verification must be redone at the start of every call, even for a caller who called earlier the same day, since caller identity cannot be assumed to carry over between separate calls.'
WHERE dept_id = 4 AND title = 'HIPAA Verbal Verification SOP v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds a documented verification-failure path: if a caller fails verification but the call appears urgent (a description suggesting an active care access problem), the agent may take a callback number and escalate to a supervisor for a judgment call, rather than simply ending the call with no further action, since a hard stop on genuinely urgent situations created its own risk. This revision also adds an explicit prohibition carried over from the original SOP intent but not previously written down directly: an agent may never confirm or deny whether a specific person is a member of the plan to a caller who has not passed verification, since even that limited disclosure is itself protected information.'
WHERE dept_id = 4 AND title = 'HIPAA Verbal Verification SOP v3';

-- --- CSAT Survey Administration Policy -----------------------------
UPDATE knowledge_docs SET content = 'A post-call satisfaction survey is offered at the end of every call except those escalated for a safety or urgent care access concern, where ending the call promptly takes priority over survey administration. The survey uses a simple 1 to 5 scale and is administered by the agent asking the member directly rather than a separate automated system, since direct administration was found to produce a higher response rate than a callback survey. A csat_score of 1 or 2 on any call is automatically flagged for supervisor review within 1 business day, regardless of whether the underlying issue was otherwise resolved, since a low score can indicate a problem with how the call was handled even when the technical issue was fixed.'
WHERE dept_id = 4 AND title = 'CSAT Survey Administration Policy';

UPDATE knowledge_docs SET content = 'Revision 2 adds an agent-neutral framing requirement to the survey question itself: the agent must ask about the member experience with the call in general terms, not phrase the question in a way that implies a specific expected answer (for example, avoiding language like did I resolve your issue today, which can pressure a member toward a higher score than they would otherwise give). This revision also extends the supervisor review window from the original 1 business day down to same-day for any score of 1 specifically, treating the lowest score as a distinct, more urgent category than a 2.'
WHERE dept_id = 4 AND title = 'CSAT Survey Administration Policy v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds a trend-based review trigger alongside the individual-score flag in revision 2: an agent whose average csat_score falls below the team average by a meaningful margin over a rolling 30-day window is flagged for a coaching conversation, independent of any single low score, since a pattern across many calls is a different signal than one difficult call. This revision also formalizes the exemption for safety-escalated calls from revision 1 to include any call transferred to the grievance unit, not just safety concerns specifically, since survey administration was found to be an awkward and sometimes distressing addition immediately after a member had just filed a formal complaint.'
WHERE dept_id = 4 AND title = 'CSAT Survey Administration Policy v3';

-- --- Call Recording Retention Policy -----------------------------
UPDATE knowledge_docs SET content = 'All member calls are recorded for quality and training purposes, with the recording retained for 2 years from the call date under standard retention. Calls involving an active grievance, a legal hold, or a regulatory inquiry are retained until the underlying matter is fully resolved, overriding the standard 2-year schedule regardless of how much longer that takes. Members are informed at the start of the call that it may be recorded, consistent with applicable state consent requirements, and the recording disclosure itself must occur before any member-specific information is discussed, not simply logged as having occurred at some point in the call.'
WHERE dept_id = 4 AND title = 'Call Recording Retention Policy';

UPDATE knowledge_docs SET content = 'Revision 2 shortens the standard retention window in revision 1 from 2 years to 18 months for calls with no flags of any kind (no grievance, no legal hold, no low CSAT score requiring review), since storage cost analysis found the marginal training value of routine, unremarkable calls dropped substantially after that point. This revision also adds explicit handling for calls flagged under the CSAT Survey Administration Policy: any call generating a supervisor review retains the standard 2-year window from revision 1 regardless of the shortened default, since those calls have ongoing coaching and pattern-analysis value.'
WHERE dept_id = 4 AND title = 'Call Recording Retention Policy v2';

UPDATE knowledge_docs SET content = 'Revision 3 adds a member-requested deletion process, distinct from the standard retention schedule in revisions 1 and 2: a member may request their call recordings be deleted earlier than the standard schedule, subject to the same legal-hold and active-grievance overrides that already apply to standard retention, and the request itself along with its resolution must be logged even when the deletion is granted, so there remains a record that a request occurred. This revision also clarifies that the recording disclosure requirement from revision 1 applies per call, not per member relationship, since a member cannot be assumed to remember or still consent based on a disclosure from a previous, separate call.'
WHERE dept_id = 4 AND title = 'Call Recording Retention Policy v3';
